def box(rows, header=False):
    if not rows: return ""
    widths=[max(len(str(r[i])) for r in rows) for i in range(len(rows[0]))]
    def line(l,m,r): return l + m.join("─"*(w+2) for w in widths) + r
    def row(r): return "│ " + " │ ".join(str(r[i]).ljust(widths[i]) for i in range(len(widths))) + " │"
    out=[line("╭","┬","╮"), row(rows[0])]
    if header and len(rows)>1: out.append(line("├","┼","┤"))
    out += [row(r) for r in rows[1:]]
    out.append(line("╰","┴","╯"))
    return "\n".join(out)

